console.log('Webhook input received:', $json);
const data = $json.body || {};
console.log('Form data departureLocation:', data.departureLocation);
console.log('Form data customAirport:', data.customAirport);

return [{
  json: {
    departureLocation: data.customAirport || data.departureLocation || "Not provided",
    destination: data.customDestination || data.destination || "Not specified",
    budget: data.budget || "~",
    tripType: data.tripType || "N/A",
    groupSize: data.groupSize || "1",
    ageRange: Array.isArray(data.ageRange) ? data.ageRange : (data.ageRange ? [data.ageRange] : ["~"]),
    dayActivity: Array.isArray(data.dayActivity) ? data.dayActivity.join(", ") : (data.dayActivity || "none"),
    nightActivity: Array.isArray(data.nightActivity) ? data.nightActivity.join(", ") : (data.nightActivity || "none"),
    startDate: data.startDate || "N/A",
    endDate: data.endDate || "N/A",
    email: data.email || "unknown"
  }
}];

console.log('Processing in Return HTML node');

const trip = $json;
console.log('Return HTML departureLocation:', trip.departureLocation);

// Generate a unique ID for this itinerary
const itineraryId = Date.now().toString();

// Prepare the itinerary data
const itineraryData = {
  tripTitle: `🌍 Trip Plan: ${trip.destination}`,
  departure: trip.departureLocation,
  dates: `${trip.startDate} to ${trip.endDate}`,
  groupSize: trip.groupSize,
  budget: `$${trip.budget}`,
  tripType: trip.tripType,
  ageRange: Array.isArray(trip.ageRange) ? trip.ageRange.join(", ") : trip.ageRange,
  dayActivity: trip.dayActivity,
  nightActivity: trip.nightActivity,
  email: trip.email,
  itinerary: trip.itinerary
};

// Use a relative path for the redirect
const baseUrl = '/travel'; // Adjusted for /travel subdirectory
const redirectUrl = `${baseUrl}/tropical_trip_itinerary.html?itineraryId=${itineraryId}`;
console.log('Setting redirect URL:', redirectUrl);

return [{
  json: {
    redirectUrl: redirectUrl,
    itineraryId: itineraryId,
    itineraryData: itineraryData
  }
}];

console.log('Processing in Prepare Email Data node');
const itineraryId = $json.query.itineraryId;
const email = $json.query.email;

// Retrieve itinerary data from the query parameters
const itineraryData = {
  destination: $json.query.destination || 'Unknown',
  departure: $json.query.departure || 'Not provided',
  dates: $json.query.dates || 'N/A',
  groupSize: $json.query.groupSize || '1',
  budget: $json.query.budget || '~',
  tripType: $json.query.tripType || 'N/A',
  ageRange: $json.query.ageRange || '~',
  dayActivity: $json.query.dayActivity || 'None',
  nightActivity: $json.query.nightActivity || 'None',
  itinerary: $json.query.itinerary || 'No itinerary found.'
};

const itineraryLink = `/travel/tropical_trip_itinerary.html?itineraryId=${itineraryId}`;

return [{
  json: {
    email: email,
    subject: `Your AI Travel Plan for ${itineraryData.destination}`,
    message: `<div style="font-family: Arial, sans-serif; background-color: #f9f9f9; padding: 20px;">
  <h2 style="color:#2a4a6e;">🌍 Trip Plan: ${itineraryData.destination}</h2>
  <p><strong>Date:</strong> ${itineraryData.dates}</p>
  <p><strong>Departure From:</strong> ${itineraryData.departure}</p>
  <p><strong>Budget:</strong> ${itineraryData.budget} (for ${itineraryData.groupSize} people)</p>
  <p><strong>Trip Type:</strong> ${itineraryData.tripType}</p>
  <p><strong>Age Ranges:</strong> ${itineraryData.ageRange}</p>
  <p><strong>Day Activities:</strong> ${itineraryData.dayActivity}</p>
  <p><strong>Night Activities:</strong> ${itineraryData.nightActivity}</p>
  <p><strong>Access Your Itinerary:</strong> <a href="${itineraryLink}">${itineraryLink}</a></p>
  <hr>
  <pre style="white-space: pre-wrap; font-size: 14px;">${itineraryData.itinerary}</pre>
  <hr>
  <p style="font-size:12px; color:#999;">Generated by Voyage Genie ✨</p>
</div>`
  }
}];
